import os
import hashlib
import hmac
import asyncio
from urllib.parse import unquote
from pathlib import PurePosixPath
import unicodedata

# Configuration
BASE_DIR = "/var/www/static"
SECRET_KEY = os.environ.get("SECRET_KEY")
if not SECRET_KEY:
    # Fail closed: refuse to run with a predictable/hardcoded secret.
    raise RuntimeError(
        "SECRET_KEY environment variable must be set to a strong, unique value."
    )
ALLOWED_EXTENSIONS = {".css", ".js", ".png", ".jpg", ".gif", ".svg", ".woff2", ".ico"}
MAX_PATH_LENGTH = 255

class RateLimiter:
    def __init__(self, max_requests=100, window=60):
        self._counts = {}
        self._window = window
        self._max = max_requests

    async def check(self, client_ip):
        import time
        now = time.time()
        if client_ip not in self._counts:
            self._counts[client_ip] = []
        self._counts[client_ip] = [
            t for t in self._counts[client_ip] if now - t < self._window
        ]
        if len(self._counts[client_ip]) >= self._max:
            return False
        self._counts[client_ip].append(now)
        return True


class AccessLogger:
    def __init__(self):
        self._log = []

    def log_access(self, client_ip, path, status):
        import time
        self._log.append({
            "timestamp": time.time(),
            "client_ip": client_ip,
            "path": path,
            "status": status
        })

    def get_recent(self, count=50):
        return self._log[-count:]


class TokenValidator:
    def __init__(self, secret):
        self._secret = secret.encode('utf-8') if isinstance(secret, str) else secret

    def generate_token(self, path, expires):
        msg = f"{path}:{expires}".encode('utf-8')
        return hmac.new(self._secret, msg, hashlib.sha256).hexdigest()

    def validate_token(self, path, token, expires):
        import time
        try:
            if time.time() > float(expires):
                return False
        except (TypeError, ValueError):
            return False
        expected = self.generate_token(path, expires)
        return hmac.compare_digest(expected, token)


def _check_extension(filepath):
    """Verify file has an allowed extension."""
    ext = os.path.splitext(filepath)[1].lower()
    return ext in ALLOWED_EXTENSIONS


def _is_safe_path_component(component):
    """Check if a single path component is safe."""
    if component in ('', '.', '..'):
        return component == ''
    if any(c in component for c in ('\\', '\x00')):
        return False
    return True


def sanitize_path(user_path):
    """Sanitize user-provided path to prevent directory traversal.

    Security approach:
    1. URL-decode the path
    2. Check for null bytes
    3. Apply Unicode normalization BEFORE security checks
    4. Normalize path separators
    5. Resolve relative components
    6. Verify result stays within BASE_DIR
    """
    if not user_path or len(user_path) > MAX_PATH_LENGTH:
        return None

    # Step 1: URL decode
    decoded_path = unquote(user_path)

    # Step 2: Check for null bytes
    if '\x00' in decoded_path:
        return None

    # Step 3: Apply Unicode normalization BEFORE path resolution
    # This ensures consistent representation before security checks
    decoded_path = unicodedata.normalize('NFC', decoded_path)

    # Step 4: Normalize separators
    cleaned = decoded_path.replace('\\', '/')

    # Step 5: Remove leading slashes for joining
    cleaned = cleaned.lstrip('/')

    # Step 6: Construct full path and resolve
    full_path = os.path.join(BASE_DIR, cleaned)

    # Step 7: Resolve to absolute path (handles ../ etc)
    resolved = os.path.realpath(full_path)

    # Step 8: Verify the resolved path is within BASE_DIR
    # SECURITY CHECK: ensure path starts with base directory
    base_resolved = os.path.realpath(BASE_DIR)
    if not resolved.startswith(base_resolved + os.sep) and resolved != base_resolved:
        return None

    return resolved


async def handle_static_request(request_path, client_ip, query_params=None):
    """Handle a request for a static file.

    Args:
        request_path: The URL path requested
        client_ip: Client's IP address
        query_params: Optional dict with 'token' and 'expires' for protected files
    """
    logger = AccessLogger()
    limiter = RateLimiter()

    # Rate limiting
    if not await limiter.check(client_ip):
        logger.log_access(client_ip, request_path, 429)
        return {"status": 429, "body": "Rate limit exceeded"}

    # Sanitize the path
    safe_path = sanitize_path(request_path)
    if safe_path is None:
        logger.log_access(client_ip, request_path, 400)
        return {"status": 400, "body": "Invalid path"}

    # Check extension
    if not _check_extension(safe_path):
        logger.log_access(client_ip, request_path, 403)
        return {"status": 403, "body": "File type not allowed"}

    # Check if file exists
    if not os.path.isfile(safe_path):
        logger.log_access(client_ip, request_path, 404)
        return {"status": 404, "body": "Not found"}

    # Check if path requires token authentication
    if '/protected/' in safe_path:
        if not query_params or 'token' not in query_params or 'expires' not in query_params:
            logger.log_access(client_ip, request_path, 401)
            return {"status": 401, "body": "Authentication required"}

        validator = TokenValidator(SECRET_KEY)
        if not validator.validate_token(request_path, query_params['token'], query_params['expires']):
            logger.log_access(client_ip, request_path, 403)
            return {"status": 403, "body": "Invalid or expired token"}

    # Serve the file
    try:
        with open(safe_path, 'rb') as f:
            content = f.read()
        logger.log_access(client_ip, request_path, 200)
        return {"status": 200, "body": content, "path": safe_path}
    except IOError:
        logger.log_access(client_ip, request_path, 500)
        return {"status": 500, "body": "Internal error"}
